// Email suppression for the shop's marketing sends.
//
// Shared state lives in STATE_DIR/suppression/<sha256 of normalized address>.ndjson.
// Each unsubscribe or resubscribe is one appended line. Appends are atomic across
// processes, so no lock is needed. The current state is the latest timestamp of
// each kind, so the order in which events arrive does not matter.
//
// Rules:
// - Marketing mail stops after an unsubscribe. A later resubscribe (by provider
//   clock) turns marketing back on. Ties go to the unsubscribe.
// - Transactional mail (order receipts, password resets) is never blocked by
//   marketing opt-out. CAN-SPAM covers commercial messages, not transactional ones.
// - Anything that cannot be verified is denied. A bad address, an unknown kind,
//   or unreadable state all stop the send.

import { createHash } from 'node:crypto';
import { mkdir, open, readFile } from 'node:fs/promises';
import path from 'node:path';

const KINDS = new Set(['marketing', 'transactional']);
const GMAIL_DOMAINS = new Set(['gmail.com', 'googlemail.com']);

// Reduce an address to the mailbox owner: strip a display name and angle brackets,
// lowercase, drop +tag aliases, and treat Gmail's dot and googlemail.com variants
// as the same account. Returns null if the input is not a usable address.
export function normalizeAddress(raw) {
  if (typeof raw !== 'string') return null;
  let s = raw.trim();
  const angle = s.match(/<([^<>]*)>\s*$/);
  if (angle) s = angle[1].trim();
  s = s.replace(/^mailto:/i, '').toLowerCase();
  if (/\s/.test(s)) return null;
  const at = s.lastIndexOf('@');
  if (at <= 0 || at === s.length - 1) return null;
  let local = s.slice(0, at);
  let domain = s.slice(at + 1);
  if (!domain.includes('.') || domain.includes('@')) return null;
  if (GMAIL_DOMAINS.has(domain)) {
    domain = 'gmail.com';
    local = local.replace(/\./g, '');
  }
  local = local.split('+')[0];
  if (!local) return null;
  return `${local}@${domain}`;
}

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  return path.join(dir, 'suppression');
}

function eventFile(address) {
  const digest = createHash('sha256').update(address).digest('hex');
  return path.join(stateDir(), `${digest}.ndjson`);
}

async function appendEvent(address, kind, at) {
  await mkdir(stateDir(), { recursive: true });
  const handle = await open(eventFile(address), 'a');
  try {
    // The leading newline ends any partial line left by a crash, so it cannot
    // swallow this record. Blank and unparseable lines are skipped when reading.
    await handle.write(`\n${JSON.stringify({ k: kind, t: at.getTime() })}\n`);
    await handle.datasync();
  } finally {
    await handle.close();
  }
}

async function readState(address) {
  let text;
  try {
    text = await readFile(eventFile(address), 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return { unsubAt: null, resubAt: null };
    throw err;
  }
  let unsubAt = null;
  let resubAt = null;
  for (const line of text.split('\n')) {
    if (!line) continue;
    let event;
    try {
      event = JSON.parse(line);
    } catch {
      continue;
    }
    if (!Number.isFinite(event?.t)) continue;
    if (event.k === 'u') unsubAt = Math.max(unsubAt ?? event.t, event.t);
    else if (event.k === 'r') resubAt = Math.max(resubAt ?? event.t, event.t);
  }
  return { unsubAt, resubAt };
}

function isMarketingOptedOut({ unsubAt, resubAt }) {
  return unsubAt !== null && (resubAt === null || unsubAt >= resubAt);
}

function checkEventArgs(email, at) {
  const address = normalizeAddress(email);
  if (!address) throw new TypeError(`invalid email address: ${String(email)}`);
  if (!(at instanceof Date) || Number.isNaN(at.getTime())) {
    throw new TypeError('at must be a valid Date');
  }
  return address;
}

export async function recordUnsubscribe(email, at) {
  const address = checkEventArgs(email, at);
  await appendEvent(address, 'u', at);
}

export async function recordResubscribe(email, at) {
  const address = checkEventArgs(email, at);
  await appendEvent(address, 'r', at);
}

const allow = () => ({ allowed: true, reason: null });
const deny = (reason) => ({ allowed: false, reason });

// `now` is accepted for the interface. None of the rules depend on it: an opt-out
// applies from the moment it is recorded, whatever the clock says.
export async function mayEmail(message, now) { // eslint-disable-line no-unused-vars
  if (!message || !KINDS.has(message.kind)) return deny('invalid_kind');
  const address = normalizeAddress(message.to);
  if (!address) return deny('invalid_recipient');
  if (message.kind === 'transactional') return allow();

  let state;
  try {
    state = await readState(address);
  } catch {
    return deny('suppression_state_unavailable');
  }
  if (isMarketingOptedOut(state)) return deny('unsubscribed');
  return allow();
}

import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g3-3/bot.mjs';
const STATE = mkdtempSync(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = STATE;
const bot = await import(BOT);
const { recordUnsubscribe, recordResubscribe, mayEmail, normalizeAddress } = bot;

const mkt = (to) => ({ to, kind: 'marketing' });
const tx = (to) => ({ to, kind: 'transactional' });
const now = new Date('2026-10-22T12:00:00Z');
const d = (s) => new Date(s);
let n = 0;
const t = (name, fn) => fn().then(() => console.log('ok  ', name), (e) => { console.log('FAIL', name, e.message); process.exitCode = 1; });

await t('normalize: display name, case, plus tag, gmail dots', async () => {
  assert.equal(normalizeAddress('Jane Doe <<EMAIL>>'), '<EMAIL>');
  assert.equal(normalizeAddress('  jane@Example.COM '), 'jane@example.com');
  assert.equal(normalizeAddress('<EMAIL>'), '<EMAIL>');
  assert.equal(normalizeAddress('mailto:<EMAIL>'), '<EMAIL>');
  assert.equal(normalizeAddress('not an email'), null);
  assert.equal(normalizeAddress('<EMAIL>'), null);
  assert.equal(normalizeAddress(42), null);
});

await t('unsubscribe blocks marketing via any alias, not transactional', async () => {
  await recordUnsubscribe('Ann <Ann+news@example.com>', d('2026-10-01T10:00:00Z'));
  assert.deepEqual(await mayEmail(mkt('ann@example.com'), now), { allowed: false, reason: 'unsubscribed' });
  assert.deepEqual(await mayEmail(mkt('ANN+x@Example.com'), now), { allowed: false, reason: 'unsubscribed' });
  assert.deepEqual(await mayEmail(tx('ann@example.com'), now), { allowed: true, reason: null });
});

await t('unrelated address unaffected', async () => {
  assert.deepEqual(await mayEmail(mkt('bob@example.com'), now), { allowed: true, reason: null });
});

await t('out of order: resubscribe older than unsubscribe does not re-enable', async () => {
  // Resubscribe at 09:00 arrives after an unsubscribe at 10:00 — unsubscribe is newer.
  await recordResubscribe('carl@example.com', d('2026-10-01T09:00:00Z'));
  await recordUnsubscribe('carl@example.com', d('2026-10-01T10:00:00Z'));
  await recordResubscribe('carl@example.com', d('2026-10-01T09:00:00Z')); // duplicate, late
  assert.equal((await mayEmail(mkt('carl@example.com'), now)).reason, 'unsubscribed');
});

await t('resubscribe newer than unsubscribe re-enables marketing, regardless of arrival order', async () => {
  await recordResubscribe('dan@example.com', d('2026-10-05T00:00:00Z'));
  await recordUnsubscribe('dan@example.com', d('2026-10-02T00:00:00Z'));
  assert.deepEqual(await mayEmail(mkt('dan@example.com'), now), { allowed: true, reason: null });
  // a later unsubscribe stops it again
  await recordUnsubscribe('dan@example.com', d('2026-10-09T00:00:00Z'));
  assert.equal((await mayEmail(mkt('dan@example.com'), now)).reason, 'unsubscribed');
});

await t('tie goes to unsubscribe', async () => {
  const at = d('2026-10-03T00:00:00Z');
  await recordResubscribe('eve@example.com', at);
  await recordUnsubscribe('eve@example.com', at);
  assert.equal((await mayEmail(mkt('eve@example.com'), now)).reason, 'unsubscribed');
});

await t('invalid input denied, not thrown', async () => {
  assert.deepEqual(await mayEmail(mkt('nope'), now), { allowed: false, reason: 'invalid_recipient' });
  assert.deepEqual(await mayEmail({ to: '<EMAIL>', kind: 'promo' }, now), { allowed: false, reason: 'invalid_kind' });
  assert.deepEqual(await mayEmail(undefined, now), { allowed: false, reason: 'invalid_kind' });
});

await t('record rejects bad args', async () => {
  await assert.rejects(recordUnsubscribe('nope', new Date()), TypeError);
  await assert.rejects(recordUnsubscribe('<EMAIL>', 'yesterday'), TypeError);
  await assert.rejects(recordResubscribe('<EMAIL>', new Date('x')), TypeError);
});

await t('torn partial line from a crash does not swallow the next event', async () => {
  const { readdirSync, appendFileSync } = await import('node:fs');
  const dir = path.join(STATE, 'suppression');
  await recordUnsubscribe('fay@example.com', d('2026-10-04T00:00:00Z'));
  const file = readdirSync(dir).map((f) => path.join(dir, f)).find((f) => f.endsWith('.ndjson') && (() => true)());
  // find fay's file by content-independent approach: write torn bytes to every file
  for (const f of readdirSync(dir)) appendFileSync(path.join(dir, f), '{"k":"u","t":12');
  await recordResubscribe('fay@example.com', d('2026-10-06T00:00:00Z'));
  assert.deepEqual(await mayEmail(mkt('fay@example.com'), now), { allowed: true, reason: null });
});

await t('STATE_DIR unset on a marketing send fails closed', async () => {
  const saved = process.env.STATE_DIR;
  delete process.env.STATE_DIR;
  const r = await mayEmail(mkt('zed@example.com'), now);
  process.env.STATE_DIR = saved;
  assert.deepEqual(r, { allowed: false, reason: 'suppression_state_unavailable' });
});

await t('concurrent workers (8 processes x 60 events) lose nothing', async () => {
  const worker = `
    process.env.STATE_DIR = ${JSON.stringify(STATE)};
    const { recordUnsubscribe, recordResubscribe } = await import(${JSON.stringify(BOT)});
    const w = Number(process.argv[2]);
    for (let i = 0; i < 60; i++) {
      const at = new Date(Date.UTC(2026, 9, 1) + (w * 60 + i) * 1000);
      if (i === 59 && w === 0) await recordUnsubscribe('race@example.com', new Date(Date.UTC(2026, 9, 20)));
      else if (i % 2) await recordResubscribe('race@example.com', at);
      else await recordUnsubscribe('race@example.com', at);
    }`;
  const procs = [...Array(8).keys()].map((w) => new Promise((res, rej) => {
    const p = spawn(process.execPath, ['--input-type=module', '-e', worker, String(w)]);
    let err = ''; p.stderr.on('data', (c) => (err += c));
    p.on('exit', (code) => (code === 0 ? res() : rej(new Error(`worker ${w} exit ${code}: ${err}`))));
  }));
  await Promise.all(procs);
  // Latest unsubscribe is 2026-10-20 (w0 i59); latest resubscribe is < that. Expect opted out.
  assert.equal((await mayEmail(mkt('race@example.com'), now)).reason, 'unsubscribed');
  // Now a resubscribe after everything should win.
  await recordResubscribe('race@example.com', new Date('2026-10-30T00:00:00Z'));
  assert.deepEqual(await mayEmail(mkt('race@example.com'), now), { allowed: true, reason: null });
});

console.log('state dir:', STATE);

